static Path backupFile(Path original) throws IOException {
    Path backup = Path.of(original.toString() + ".bak");
    try (FileReader reader = new FileReader(original.toFile());
         FileWriter writer = new FileWriter(backup.toFile())) {
        int c;
        while ((c = reader.read()) != -1) {
            writer.write(c);
        }
    }
    return backup;
}

