static char shift(char c, int amount) {
    if (Character.isLowerCase(c)) {
        return (char) ('a' + Math.floorMod(c - 'a' + amount, 26));
    } else if (Character.isUpperCase(c)) {
        return (char) ('A' + Math.floorMod(c - 'A' + amount, 26));
    }
    return c;
}

